13	// ErrNotFound is returned when a queried row does not exist.
14	var ErrNotFound = errors.New("not found")
15	
16	// Reader executes read-only SQL queries against the shared PostgreSQL schema.
17	// All UUID parameters are accepted as hex strings and parsed internally.
18	type Reader struct {
19		db *Pool
20	}
