47	// ListWorkspaces returns all workspaces ordered by updated_at desc.
48	func (r *Reader) ListWorkspaces(ctx context.Context) ([]Workspace, error) {
49		const q = `
50			SELECT id, slug, name, management_repo_id, branch_pattern, created_at, updated_at
51			FROM workspaces
52			ORDER BY updated_at DESC`
53		rows, err := r.db.Query(ctx, q)
54		if err != nil {
55			return nil, err
56		}
57		defer rows.Close()
58		var out []Workspace
