60			var w Workspace
61			if err := rows.Scan(&w.ID, &w.Slug, &w.Name, &w.ManagementRepoID, &w.BranchPattern, &w.CreatedAt, &w.UpdatedAt); err != nil {
62				return nil, err
63			}
64			out = append(out, w)
65		}
66		return out, rows.Err()
67	}
