69	// GetWorkspace returns a single workspace by UUID string.
70	// Returns ErrNotFound if no row exists.
71	func (r *Reader) GetWorkspace(ctx context.Context, workspaceID string) (Workspace, error) {
72		uid, err := parseUUID(workspaceID)
73		if err != nil {
74			return Workspace{}, err
75		}
76		const q = `
77			SELECT id, slug, name, management_repo_id, branch_pattern, created_at, updated_at
78			FROM workspaces WHERE id = $1`
79		row := r.db.QueryRow(ctx, q, uid)
80		var w Workspace
81		if err := row.Scan(&w.ID, &w.Slug, &w.Name, &w.ManagementRepoID, &w.BranchPattern, &w.CreatedAt, &w.UpdatedAt); err != nil {
82			if errors.Is(err, pgx.ErrNoRows) {
83				return Workspace{}, ErrNotFound
