132	// ListLatestSyncRunsPerWorkspace returns one sync run per workspace (the most recent).
133	func (r *Reader) ListLatestSyncRunsPerWorkspace(ctx context.Context) ([]WorkspaceSyncRun, error) {
134		const q = `
135			SELECT DISTINCT ON (workspace_id)
136			       id, workspace_id, trigger, branch, feature_id, task_id, mode, status,
137			       commit_sha, changed_paths, started_at, finished_at, error_code, error_message, metadata
138			FROM workspace_sync_runs
