156	// GetLatestSyncRun returns the most recent sync run for a workspace.
157	// Returns ErrNotFound if no row exists.
158	func (r *Reader) GetLatestSyncRun(ctx context.Context, workspaceID string) (WorkspaceSyncRun, error) {
159		uid, err := parseUUID(workspaceID)
160		if err != nil {
161			return WorkspaceSyncRun{}, err
162		}
163		const q = `
164			SELECT id, workspace_id, trigger, branch, feature_id, task_id, mode, status,
165			       commit_sha, changed_paths, started_at, finished_at, error_code, error_message, metadata
166			FROM workspace_sync_runs
167			WHERE workspace_id = $1
168			ORDER BY started_at DESC
169			LIMIT 1`
170		row := r.db.QueryRow(ctx, q, uid)
171		var s WorkspaceSyncRun
172		if err := row.Scan(
173			&s.ID, &s.WorkspaceID, &s.Trigger, &s.Branch, &s.FeatureID, &s.TaskID,
174			&s.Mode, &s.Status, &s.CommitSha, &s.ChangedPaths,
