194			FROM workspace_features
195			WHERE workspace_id = $1
196			ORDER BY updated_at DESC`
197		rows, err := r.db.Query(ctx, q, uid)
198		if err != nil {
199			return nil, err
200		}
201		defer rows.Close()
202		var out []WorkspaceFeature
203		for rows.Next() {
