213	// SearchWorkspaceFeatures returns workspace features filtered by search/title/status with safe sorting and limiting.
214	func (r *Reader) SearchWorkspaceFeatures(ctx context.Context, workspaceID string, filters FeatureSearchFilters) ([]WorkspaceFeature, error) {
215		uid, err := parseUUID(workspaceID)
216		if err != nil {
217			return nil, err
218		}
219	
220		where, args, argPos := buildFeatureWhere(uid, filters)
221	
222		orderBy := "updated_at DESC, feature_name ASC"
223		switch filters.Sort {
224		case "title_asc":
225			orderBy = "title ASC, feature_name ASC"
226		case "title_desc":
227			orderBy = "title DESC, feature_name ASC"
228		case "status_asc":
229			orderBy = "feature_status ASC NULLS LAST, feature_name ASC"
230		case "status_desc":
231			orderBy = "feature_status DESC NULLS LAST, feature_name ASC"
232		case "updated_at_asc", "time_asc", "createdAt":
233			orderBy = "updated_at ASC, feature_name ASC"
234		case "updated_at_desc", "time_desc", "-createdAt", "":
235			orderBy = "updated_at DESC, feature_name ASC"
236		}
237	
238		limitClause := ""
239		if filters.Limit > 0 {
240			limitClause = fmt.Sprintf(" LIMIT $%d", argPos)
241			args = append(args, filters.Limit)
242			argPos++
243		}
244		offsetClause := ""
245		if filters.Page > 1 && filters.Limit > 0 {
246			offsetClause = fmt.Sprintf(" OFFSET $%d", argPos)
247			args = append(args, (filters.Page-1)*filters.Limit)
248		}
249	
250		q := fmt.Sprintf(`
251			SELECT id, workspace_id, feature_id, feature_name, title, feature_status, current_stage, next_action,
252			       stages, source_path, source_hash, created_at, updated_at
253			FROM workspace_features
254			WHERE %s
255			ORDER BY %s%s%s`, strings.Join(where, " AND "), orderBy, limitClause, offsetClause)
256		rows, err := r.db.Query(ctx, q, args...)
257		if err != nil {
258			return nil, err
259		}
260		defer rows.Close()
261		var out []WorkspaceFeature
262		for rows.Next() {
263			var f WorkspaceFeature
264			if err := scanFeature(rows, &f); err != nil {
265				return nil, err
266			}
267			out = append(out, f)
268		}
269		return out, rows.Err()
270	}
