573	// UUIDString converts a pgtype.UUID to its hex string representation.
574	func UUIDString(u pgtype.UUID) string {
575		if !u.Valid {
576			return ""
577		}
578		b := u.Bytes
579		return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",
580			b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
581	}
