593	// buildFeatureWhere constructs the WHERE clause conditions for feature search/count queries.
594	func buildFeatureWhere(workspaceUID pgtype.UUID, filters FeatureSearchFilters) ([]string, []interface{}, int) {
595		where := []string{"workspace_id = $1"}
596		args := []interface{}{workspaceUID}
597		argPos := 2
598		if filters.Title != "" {
599			where = append(where, fmt.Sprintf("title ILIKE $%d", argPos))
600			args = append(args, "%"+filters.Title+"%")
601			argPos++
602		}
603		if filters.Status != "" {
604			statuses := splitCSV(filters.Status)
605			if len(statuses) == 1 {
606				where = append(where, fmt.Sprintf("feature_status = $%d", argPos))
607				args = append(args, statuses[0])
608				argPos++
609			} else if len(statuses) > 1 {
610				where = append(where, fmt.Sprintf("feature_status = ANY($%d)", argPos))
611				args = append(args, statuses)
612				argPos++
613			}
614		}
615		return where, args, argPos
616	}
