618	// buildTaskWhere constructs the WHERE clause conditions for task search/count queries.
619	func buildTaskWhere(baseWhere []string, baseArgs []interface{}, argPos int, filters TaskSearchFilters) ([]string, []interface{}, int) {
620		where := make([]string, len(baseWhere), len(baseWhere)+4)
621		copy(where, baseWhere)
622		args := make([]interface{}, len(baseArgs), len(baseArgs)+4)
623		copy(args, baseArgs)
624		if filters.TaskID != "" {
625			where = append(where, fmt.Sprintf("t.task_name ILIKE $%d", argPos))
626			args = append(args, "%"+filters.TaskID+"%")
627			argPos++
628		}
629		if filters.Title != "" {
630			where = append(where, fmt.Sprintf("t.title ILIKE $%d", argPos))
631			args = append(args, "%"+filters.Title+"%")
632			argPos++
633		}
634		if filters.Status != "" {
635			statuses := splitCSV(filters.Status)
636			if len(statuses) == 1 {
637				where = append(where, fmt.Sprintf("t.status = $%d", argPos))
638				args = append(args, statuses[0])
639				argPos++
640			} else if len(statuses) > 1 {
641				where = append(where, fmt.Sprintf("t.status = ANY($%d)", argPos))
642				args = append(args, statuses)
643				argPos++
644			}
645		}
646		if filters.Repo != "" {
647			where = append(where, fmt.Sprintf("t.repo = $%d", argPos))
648			args = append(args, filters.Repo)
649			argPos++
650		}
651		return where, args, argPos
652	}
