703	func taskIDOrderAsc() string {
704		return fmt.Sprintf("%s ASC NULLS LAST, t.task_name ASC", taskIDNumberExpr())
705	}
706	
707	func taskIDOrderDesc() string {
708		return fmt.Sprintf("%s DESC NULLS LAST, t.task_name DESC", taskIDNumberExpr())
709	}
710	
711	func taskIDNumberExpr() string {
712		return "NULLIF(regexp_replace(t.task_name, '^T([0-9]+)$', '\\1'), t.task_name)::int"
713	}
714	
715	func activityFilterClause(featureID, taskID string, firstArg int) (string, []interface{}, int, error) {
716		var where []string
717		var args []interface{}
718		argPos := firstArg
719		if featureID != "" {
720			fid, err := parseUUID(featureID)
721			if err != nil {
722				return "", nil, argPos, err
723			}
724			where = append(where, fmt.Sprintf("feature_id = $%d", argPos))
725			args = append(args, fid)
726			argPos++
727		}
728		if taskID != "" {
729			tid, err := parseUUID(taskID)
730			if err != nil {
731				return "", nil, argPos, err
732			}
733			where = append(where, fmt.Sprintf("task_id = $%d", argPos))
734			args = append(args, tid)
735			argPos++
736		}
737		if len(where) == 0 {
738			return "", nil, argPos, nil
739		}
740		return " AND " + strings.Join(where, " AND "), args, argPos, nil
741	}
