743	func (r *Reader) searchTasks(ctx context.Context, baseWhere []string, baseArgs []interface{}, argPos int, filters TaskSearchFilters) ([]WorkspaceTask, error) {
744		where, args, argPos := buildTaskWhere(baseWhere, baseArgs, argPos, filters)
745	
746		orderBy := taskIDOrderAsc()
747		switch filters.Sort {
748		case "task_id_desc":
749			orderBy = taskIDOrderDesc()
750		case "title_asc":
751			orderBy = "t.title ASC, " + taskIDOrderAsc()
752		case "title_desc":
753			orderBy = "t.title DESC, " + taskIDOrderAsc()
754		case "status_asc":
755			orderBy = "t.status ASC NULLS LAST, " + taskIDOrderAsc()
756		case "status_desc":
757			orderBy = "t.status DESC NULLS LAST, " + taskIDOrderAsc()
758		case "repo_asc":
759			orderBy = "t.repo ASC NULLS LAST, " + taskIDOrderAsc()
760		case "repo_desc":
761			orderBy = "t.repo DESC NULLS LAST, " + taskIDOrderAsc()
762		case "updated_at_asc", "time_asc", "createdAt":
763			orderBy = "t.updated_at ASC, " + taskIDOrderAsc()
764		case "updated_at_desc", "time_desc", "-createdAt":
765			orderBy = "t.updated_at DESC, " + taskIDOrderAsc()
766		case "task_id_asc", "":
767			orderBy = taskIDOrderAsc()
768		}
