	if err := row.Scan(&s.ID, &s.WorkspaceID, &s.RepoURL, &s.RepoOwner, &s.RepoName, &s.DefaultBranch, &s.CreatedAt, &s.UpdatedAt); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return WorkspaceGitHubSource{}, ErrNotFound
		}
