		FROM workspace_features
		WHERE workspace_id = $1
		ORDER BY updated_at DESC`
	rows, err := r.db.Query(ctx, q, uid)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []WorkspaceFeature
	for rows.Next() {
