369	// SearchTasks returns paged task summaries for a feature filtered by search/task_id/title/status/repo.
370	func (s *WorkspaceService) SearchTasks(ctx context.Context, workspaceID, featureID string, query domain.TaskSearchQuery) (*domain.PagedTasks, domain.SourceError) {
371		if query.Page == 0 {
372			query.Page = 1
373		}
374		if query.Page < 1 {
375			return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "page must be greater than or equal to 1")
376		}
377		if query.Limit < 0 {
378			return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "limit must be greater than or equal to 0")
379		}
380		if query.Sort != "" && !isValidTaskSearchSort(query.Sort) {
381			return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "sort must be one of task_id_asc, task_id_desc, title_asc, title_desc, status_asc, status_desc, repo_asc, repo_desc, updated_at_asc, updated_at_desc, time_asc, time_desc, createdAt, -createdAt")
382		}
383	
384		feat, err := s.db.GetWorkspaceFeature(ctx, workspaceID, featureID)
385		if err != nil {
386			if errors.Is(err, database2.ErrNotFound) {
387				return nil, domain.NewDatabaseNotFound("feature", featureID)
388			}
389			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
390		}
391		featureUUID := database2.UUIDString(feat.FeatureID)
392	
393		filters := database2.TaskSearchFilters{
394			TaskID: query.TaskID,
395			Title:  query.Title,
396			Status: query.Status,
397			Repo:   query.Repo,
398			Sort:   query.Sort,
399			Page:   query.Page,
400			Limit:  query.Limit,
401		}
402		tasks, err := s.db.SearchFeatureTasks(ctx, workspaceID, featureUUID, filters)
403		if err != nil {
404			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
405		}
406		total, err := s.db.CountFeatureTasks(ctx, workspaceID, featureUUID, filters)
407		if err != nil {
408			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
409		}
410	
411		items := make([]domain.TaskSummary, 0, len(tasks))
412		for _, t := range tasks {
413			items = append(items, toTaskSummary(t))
414		}
415		return &domain.PagedTasks{Items: items, Total: total, Page: query.Page, Limit: query.Limit}, domain.SourceError{}
416	}
417	
418	// SearchWorkspaceTasks returns paged task summaries for a workspace filtered by search/task_id/title/status/repo.
419	func (s *WorkspaceService) SearchWorkspaceTasks(ctx context.Context, workspaceID string, query domain.TaskSearchQuery) (*domain.PagedTasks, domain.SourceError) {
420		if query.Page == 0 {
421			query.Page = 1
422		}
423		if query.Page < 1 {
424			return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "page must be greater than or equal to 1")
425		}
426		if query.Limit < 0 {
427			return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "limit must be greater than or equal to 0")
428		}
429		if query.Sort != "" && !isValidTaskSearchSort(query.Sort) {
430			return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "sort must be one of task_id_asc, task_id_desc, title_asc, title_desc, status_asc, status_desc, repo_asc, repo_desc, updated_at_asc, updated_at_desc, time_asc, time_desc, createdAt, -createdAt")
431		}
432	
433		filters := database2.TaskSearchFilters{
434			TaskID: query.TaskID,
435			Title:  query.Title,
436			Status: query.Status,
437			Repo:   query.Repo,
438			Sort:   query.Sort,
439			Page:   query.Page,
440			Limit:  query.Limit,
441		}
442		tasks, err := s.db.SearchWorkspaceTasks(ctx, workspaceID, filters)
443		if err != nil {
444			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
445		}
446		total, err := s.db.CountWorkspaceTasks(ctx, workspaceID, filters)
447		if err != nil {
448			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
449		}
450	
451		items := make([]domain.TaskSummary, 0, len(tasks))
452		for _, t := range tasks {
453			items = append(items, toTaskSummary(t))
454		}
455		return &domain.PagedTasks{Items: items, Total: total, Page: query.Page, Limit: query.Limit}, domain.SourceError{}
456	}
