458	// SearchFeatures returns paged feature summaries for a workspace filtered by search/title/status.
459	func (s *WorkspaceService) SearchFeatures(ctx context.Context, workspaceID string, query domain.FeatureSearchQuery) (*domain.PagedFeatures, domain.SourceError) {
460		if query.Page == 0 {
461			query.Page = 1
462		}
463		if query.Page < 1 {
464			return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "page must be greater than or equal to 1")
465		}
466		if query.Limit < 0 {
467			return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "limit must be greater than or equal to 0")
468		}
469		if query.Sort != "" && !isValidSearchSort(query.Sort) {
470			return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "sort must be one of title_asc, title_desc, status_asc, status_desc, updated_at_asc, updated_at_desc, time_asc, time_desc, createdAt, -createdAt")
471		}
472	
473		filters := database2.FeatureSearchFilters{
474			Title:  query.Title,
475			Status: query.Status,
476			Sort:   query.Sort,
477			Page:   query.Page,
478			Limit:  query.Limit,
479		}
480		features, err := s.db.SearchWorkspaceFeatures(ctx, workspaceID, filters)
481		if err != nil {
482			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
483		}
484	
485		total, err := s.db.CountWorkspaceFeatures(ctx, workspaceID, filters)
486		if err != nil {
487			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
488		}
489	
490		taskCountsByFeature := map[string]domain.TaskCounts{}
491		if len(features) > 0 {
492			countRows, err := s.db.ListFeatureTaskCounts(ctx, workspaceID, featureIDs(features))
493			if err != nil {
494				return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
495			}
496			taskCountsByFeature = taskCountsFromRows(countRows)
497		}
498	
499		items := make([]domain.FeatureSummary, 0, len(features))
500		for _, f := range features {
501			counts := taskCountsByFeature[database2.UUIDString(f.FeatureID)]
502			items = append(items, domain.FeatureSummary{
503				ID:           database2.UUIDString(f.ID),
504				FeatureID:    database2.UUIDString(f.FeatureID),
505				FeatureName:  f.FeatureName,
506				Title:        f.Title,
507				Status:       derefStr(f.FeatureStatus),
508				CurrentStage: derefStr(f.CurrentStage),
509				Stages:       rawJSONOrNil(f.Stages),
510				UpdatedAt:    f.UpdatedAt.Time,
511				TaskCounts:   counts,
512			})
513		}
514		return &domain.PagedFeatures{Items: items, Total: total, Page: query.Page, Limit: query.Limit}, domain.SourceError{}
515	}
