566				return nil, domain.NewDatabaseNotFound("task", taskID)
567			}
568			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
569		}
570	
571		activity, err := s.db.ListActivityEvents(ctx, wsID, database2.UUIDString(t.FeatureID), database2.UUIDString(t.TaskID))
572		if err != nil {
