714	func toActivityEvent(a database2.WorkspaceActivityEvent) domain.ActivityEvent {
715		e := domain.ActivityEvent{
716			Action:    derefStr(a.Action),
717			Scope:     a.ScopeType,
718			Actor:     derefStr(a.Actor),
719			Note:      derefStr(a.Note),
720			FeatureID: database2.UUIDString(a.FeatureID),
721			TaskID:    database2.UUIDString(a.TaskID),
722		}
723		if a.OccurredAt != nil {
724			if t, err := time.Parse(time.RFC3339, *a.OccurredAt); err == nil {
725				e.OccurredAt = t
726			}
727		}
728		return e
729	}
