126		}
127	
128		var apiErr domain.APIError
129		if err := json.Unmarshal(data, &apiErr); err == nil && apiErr.Code != "" && apiErr.Source != "" {
130			msg := apiErr.Message
131			if msg == "" {
132				msg = fmt.Sprintf("adapter-service returned HTTP %d", statusCode)
133			}
134			return domain.SourceError{
135				Code:      apiErr.Code,
136				Message:   msg,
137				Source:    apiErr.Source,
138				Retryable: apiErr.Retryable,
139			}
140		}
141	
142		return sourceErrorFromHTTPStatus(path, statusCode, data)
143	}
144	
145	func sourceErrorFromHTTPStatus(path string, statusCode int, data []byte) domain.SourceError {
146		message := fmt.Sprintf("adapter-service %s returned HTTP %d", path, statusCode)
147		if len(data) > 0 {
148			message = fmt.Sprintf("%s: %s", message, string(data))
149		}
150	
