158		case http.StatusRequestTimeout, http.StatusGatewayTimeout:
159			return domain.SourceError{Code: domain.ErrAdapterTimeout, Message: message, Source: domain.ErrorSourceAdapter, Retryable: true}
160		default:
161			return domain.SourceError{Code: domain.ErrAdapterInternal, Message: message, Source: domain.ErrorSourceAdapter, Retryable: statusCode >= 500}
