	case http.StatusNotFound:
		return domain.SourceError{Code: domain.ErrGitHubNotFound, Message: message, Source: domain.ErrorSourceGitHub, Retryable: false}
	case http.StatusRequestTimeout, http.StatusGatewayTimeout:
