	const path = "/internal/workspaces/import"
	resp, statusCode, err := c.post(ctx, path, body)
	if err != nil {
		return "", err
	}
	if statusCode != http.StatusOK && statusCode != http.StatusAccepted {
		return "", sourceErrorFromHTTPStatus(path, statusCode, resp) // TODO: Test
