// --- conversion helpers ---

func toSourceState(run *database2.WorkspaceSyncRun, threshold time.Duration) domain.SourceState {
	if run == nil {
		return domain.DeriveSourceState(nil, threshold)
	}
	sr := &domain.SyncRun{
		ID:          database2.UUIDString(run.ID),
		WorkspaceID: database2.UUIDString(run.WorkspaceID),
		Trigger:     run.Trigger,
		Mode:        run.Mode,
		Status:      domain.SyncStatus(run.Status),
		StartedAt:   run.StartedAt.Time,
	}
	if run.FinishedAt.Valid {
		t := run.FinishedAt.Time
		sr.FinishedAt = &t
	}
	if run.CommitSha != nil {
		sr.CommitSHA = *run.CommitSha
	}
	if run.ErrorCode != nil {
		sr.ErrorCode = *run.ErrorCode
	}
	if run.ErrorMessage != nil {
		sr.ErrorMsg = *run.ErrorMessage
	}
	return domain.DeriveSourceState(sr, threshold)
}

func toTaskSummary(t database2.WorkspaceTask) domain.TaskSummary {
	isBlocked := t.Status != nil && *t.Status == "blocked"
	return domain.TaskSummary{
		ID:            database2.UUIDString(t.ID),
		TaskID:        database2.UUIDString(t.TaskID),
		TaskName:      t.TaskName,
		FeatureID:     database2.UUIDString(t.FeatureID),
		FeatureName:   t.FeatureName,
		Title:         t.Title,
		Status:        derefStr(t.Status),
		Repo:          derefStr(t.Repo),
		Branch:        derefStr(t.Branch),
		IsBlocked:     isBlocked,
		BlockedReason: derefStr(t.BlockedReason),
		Pr:            rawJSONOrNil(t.Pr),
		WorkspacePr:   rawJSONOrNil(t.WorkspacePr),
	}
}

func toActivityEvent(a database2.WorkspaceActivityEvent) domain.ActivityEvent {
	e := domain.ActivityEvent{
		Action:    derefStr(a.Action),
		Scope:     a.ScopeType,
		Actor:     derefStr(a.Actor),
		Note:      derefStr(a.Note),
		FeatureID: database2.UUIDString(a.FeatureID),
		TaskID:    database2.UUIDString(a.TaskID),
	}
	if a.OccurredAt != nil {
		if t, err := time.Parse(time.RFC3339, *a.OccurredAt); err == nil {
			e.OccurredAt = t
		}
	}
	return e
}

func isValidSearchSort(sort string) bool {
	switch sort {
	case "title_asc", "title_desc", "status_asc", "status_desc", "updated_at_asc", "updated_at_desc", "time_asc", "time_desc", "createdAt", "-createdAt":
		return true
	default:
		return false
	}
}

func isValidTaskSearchSort(sort string) bool {
	switch sort {
	case "task_id_asc", "task_id_desc", "title_asc", "title_desc", "status_asc", "status_desc", "repo_asc", "repo_desc", "updated_at_asc", "updated_at_desc", "time_asc", "time_desc", "createdAt", "-createdAt":
		return true
	default:
		return false
	}
}

func featureIDs(features []database2.WorkspaceFeature) []string {
	ids := make([]string, 0, len(features))
	for _, feature := range features {
		ids = append(ids, database2.UUIDString(feature.FeatureID))
	}
	return ids
}

func taskCountsFromRows(rows []database2.WorkspaceFeatureTaskCounts) map[string]domain.TaskCounts {
	counts := make(map[string]domain.TaskCounts, len(rows))
	for _, row := range rows {
		counts[database2.UUIDString(row.FeatureID)] = domain.TaskCounts{
			Total:      int(row.Total),
			Done:       int(row.Done),
			InProgress: int(row.InProgress),
			Blocked:    int(row.Blocked),
			Ready:      int(row.Ready),
			Todo:       int(row.Todo),
		}
	}
	return counts
}

func countTasksByFeature(tasks []database2.WorkspaceTask) map[string]domain.TaskCounts {
	counts := make(map[string]domain.TaskCounts, len(tasks))
	for _, t := range tasks {
		featureID := database2.UUIDString(t.FeatureID)
		current := counts[featureID]
		current.Total++
		if t.Status != nil {
			switch *t.Status {
			case "done":
				current.Done++
			case "in_progress":
				current.InProgress++
			case "blocked":
				current.Blocked++
			case "ready":
				current.Ready++
			case "todo":
				current.Todo++
			}
		}
		counts[featureID] = current
	}
	return counts
}

func countTasks(tasks []database2.WorkspaceTask) domain.TaskCounts {
	var counts domain.TaskCounts
	for _, t := range tasks {
		counts.Total++
		if t.Status != nil {
			switch *t.Status {
			case "done":
				counts.Done++
			case "in_progress":
				counts.InProgress++
			case "blocked":
				counts.Blocked++
			case "ready":
				counts.Ready++
			case "todo":
				counts.Todo++
			}
		}
	}
	return counts
}

func parsePRRefs(prData, workspacePRData []byte, repo string) []domain.PullRequestRef {
	var refs []domain.PullRequestRef

	var pr map[string]interface{}
	if prData != nil {
		if json.Unmarshal(prData, &pr) == nil {
			if url, ok := pr["url"].(string); ok && url != "" {
				status, _ := pr["status"].(string)
				refs = append(refs, domain.PullRequestRef{
					Label:  "Implementation PR",
					URL:    url,
					Status: status,
					Repo:   repo,
				})
			}
		}
	}

	var wsPR map[string]interface{}
	if workspacePRData != nil {
		if json.Unmarshal(workspacePRData, &wsPR) == nil {
			if url, ok := wsPR["url"].(string); ok && url != "" {
				status, _ := wsPR["status"].(string)
				refs = append(refs, domain.PullRequestRef{
					Label:  "Workspace PR",
					URL:    url,
					Status: status,
					Repo:   "management-repo",
				})
			}
		}
	}
	return refs
}

func derefStr(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func rawJSONOrNil(raw json.RawMessage) json.RawMessage {
	if len(raw) == 0 || string(raw) == "null" || !json.Valid(raw) {
		return nil
	}
	return raw
}

// Package api provides the cobra subcommand for starting the HTTP API server.
package api

import (
	"context"
	"fmt"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/gin-contrib/requestid"
	"github.com/gin-gonic/gin"
	"github.com/rs/zerolog/log"
	"github.com/spf13/cobra"

	"github.com/tiendv89/workflow-backend/configs"
	"github.com/tiendv89/workflow-backend/internal/adapter"
	apimiddleware "github.com/tiendv89/workflow-backend/internal/app/api/middleware"
	"github.com/tiendv89/workflow-backend/internal/database"
	"github.com/tiendv89/workflow-backend/internal/handler"
	"github.com/tiendv89/workflow-backend/internal/service"
)

const maxRequestBodyBytes = 1 << 20 // 1 MB

var skipPaths = map[string]struct{}{
	"/healthz": {},
}

// Command is the cobra subcommand for starting the HTTP API server.
var Command = &cobra.Command{
	Use:   "api",
	Short: "Start the HTTP API server",
	RunE: func(cmd *cobra.Command, args []string) error {
		return run(configs.G)
	},
}

func run(cfg *configs.Config) error {
	if cfg.DB.AutoMigration {
		migCtx, migCancel := context.WithTimeout(context.Background(), 2*time.Minute)
		if err := database.RunMigrations(migCtx, cfg.DB.DSN()); err != nil {
			migCancel()
			return fmt.Errorf("migrations: %w", err)
		}
		migCancel()
	}

	connCtx, connCancel := context.WithTimeout(context.Background(), 15*time.Second)
	pool, err := database.Connect(connCtx, cfg.DB)
	connCancel()
	if err != nil {
		return fmt.Errorf("database: %w", err)
	}
	defer pool.Close()

	reader := database.NewReader(pool)
	adapterClient := adapter.New(cfg.API.AdapterServiceURL)
	svc := service.New(reader, adapterClient, cfg.StaleThreshold())

	gin.SetMode(cfg.API.HTTP.Mode)

	r := gin.New()
	r.Use(requestid.New())
	r.Use(apimiddleware.Log(skipPaths))
	r.Use(gin.Recovery())
	r.Use(corsMiddleware())
	r.Use(maxBodySizeMiddleware())

	r.GET("/healthz", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"status": "ok"})
	})

	api := r.Group("/api")
	h := handler.New(svc)
	h.RegisterRoutes(api)

	srv := &http.Server{
		Addr:         cfg.API.HTTP.Address,
		Handler:      r,
		ReadTimeout:  15 * time.Second,
		WriteTimeout: 30 * time.Second,
		IdleTimeout:  120 * time.Second,
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	go func() {
		log.Info().Str("address", cfg.API.HTTP.Address).Msg("api-service listening")
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatal().Err(err).Msg("listen failed")
		}
	}()

	<-ctx.Done()
	log.Info().Msg("api-service: shutting down")

	shutCtx, shutCancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer shutCancel()

	if err := srv.Shutdown(shutCtx); err != nil {
		log.Error().Err(err).Msg("shutdown error")
	}
	return nil
}

func corsMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		c.Header("Access-Control-Allow-Origin", "*")
		c.Header("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
		c.Header("Access-Control-Allow-Headers", "Origin, Content-Type, Accept, Authorization")
		c.Header("Access-Control-Max-Age", "86400")
		if c.Request.Method == http.MethodOptions {
			c.AbortWithStatus(http.StatusNoContent)
			return
		}
		c.Next()
	}
}

func maxBodySizeMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, maxRequestBodyBytes)
		c.Next()
	}
}

