	callCount := 0
	srv := makeServer(t, func(w http.ResponseWriter, r *http.Request) {
		callCount++
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"user_id":                  "cached-user",
			"accessible_workspace_ids": []string{"ws-1"},
