package authmw_test

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/gin-gonic/gin"

	"github.com/tiendv89/workflow-backend/internal/authmw"
	usersvc "github.com/tiendv89/workflow-backend/internal/serviceclient/user_service"
)

// stubServer is a tiny httptest.Server that returns a canned session validate response.
func stubServer(t *testing.T, statusCode int, body interface{}) *usersvc.Client {
	t.Helper()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(statusCode)
		if body != nil {
			_ = json.NewEncoder(w).Encode(body)
		}
	}))
	t.Cleanup(srv.Close)
	return usersvc.New(usersvc.Config{
		InternalURL: srv.URL,
		Token:       "test-token",
	})
}

func ginRouter(mw gin.HandlerFunc) (*gin.Engine, *httptest.ResponseRecorder) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.Use(mw)
	r.GET("/api/test", func(c *gin.Context) {
		ac, ok := authmw.FromContext(c.Request.Context())
		if !ok {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "no auth context"})
			return
		}
		c.JSON(http.StatusOK, gin.H{
			"user_id":      ac.UserID,
			"org_id":       ac.OrganizationID,
			"workspaces":   ac.AccessibleWorkspaceIDs,
		})
	})
	w := httptest.NewRecorder()
	return r, w
}

func TestRequireAuth_ValidSession(t *testing.T) {
	client := stubServer(t, http.StatusOK, map[string]interface{}{
		"user_id":                  "user-123",
		"organization_id":          "org-456",
		"accessible_workspace_ids": []string{"ws-aaa"},
	})

	r, w := ginRouter(authmw.RequireAuth(client))
	req, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, "/api/test", nil)
	req.AddCookie(&http.Cookie{Name: "session", Value: "valid-cookie"})
	r.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Errorf("expected 200, got %d: %s", w.Code, w.Body.String())
	}

	var body map[string]interface{}
