			"user_id":                  "cached-user",
			"accessible_workspace_ids": []string{"ws-1"},
		})
	})

	client := newClient(t, srv.URL)
	ctx := context.Background()

	_, _ = client.ValidateSession(ctx, "cookie-value")
	_, _ = client.ValidateSession(ctx, "cookie-value")
	_, _ = client.ValidateSession(ctx, "cookie-value")

	if callCount != 1 {
		t.Errorf("expected 1 HTTP call (cached), got %d", callCount)
	}
}

